// Package lbdsrc carries the lbd kernel module's C source, embedded in the
// miren binary so a node can compile the module without fetching anything.
//
// The source under src/ is generated by hack/sync-lbd-src.sh from the
// miren.dev/lbd version that go.mod pins; see README.md.
package lbdsrc

import "embed"

// FS holds the module source rooted at "src". Its "src/VERSION" file records
// the miren.dev/lbd version the tree was copied from.
//
//go:embed all:src
var FS embed.FS

// Version reports the miren.dev/lbd version this source was copied from.
func Version() string {
	data, err := FS.ReadFile("src/VERSION")
	if err != nil {
		// VERSION is written by the sync script alongside the source it
		// describes, so its absence means the embed itself is broken.
		return "unknown"
	}
	return trimNewline(string(data))
}

func trimNewline(s string) string {
	for len(s) > 0 && (s[len(s)-1] == '\n' || s[len(s)-1] == '\r') {
		s = s[:len(s)-1]
	}
	return s
}
